// v modulo m, always in [0, m).
export const wrap = (v: number, m: number) => ((v % m) + m) % m

// A stable value in [0, 1) for an integer seed.
export const hash = (n: number) => {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453
  return x - Math.floor(x)
}

